/* Delta codes as (code << 5) | length, one book after another; see sbr_bitstream.c
 * for where each starts. */
/* Bits above the low six are all ones in every envelope code. Keep the
 * normative full codes below, but store only those six bits and the length.
 * The writer restores the leading ones; PutBit masks to the code length. */
#define SBR_CODE(code, bits) (((code & 63) << 5) | bits)

